<template><div class="page"><div class="page-header"><h2>报表中心</h2></div><el-row :gutter="16"><el-col :span="8"><el-card shadow="never"><template #header><span style="font-weight:600">库存快照</span></template><div style="text-align:center;padding:20px;color:#409eff;font-size:32px;font-weight:700">--</div><div style="text-align:center;color:#909399;font-size:13px">选择仓库查看当前库存</div><div style="margin-top:12px"><el-select v-model="snapshotWhcd" size="small" style="width:100%" placeholder="选择仓库"><el-option label="全部仓库" value=""/></el-select></div><div style="margin-top:8px;text-align:right"><el-button type="primary" size="small" @click="loadSnapshot">查询</el-button></div></el-card></el-col><el-col :span="8"><el-card shadow="never"><template #header><span style="font-weight:600">库存预警</span></template><div style="text-align:center;padding:20px"><el-tag type="danger" size="large" effect="dark" style="font-size:24px;padding:8px 20px">{{ alertCount }}</el-tag></div><div style="text-align:center;color:#909399;font-size:13px">低于下限的物料数</div></el-card></el-col><el-col :span="8"><el-card shadow="never"><template #header><span style="font-weight:600">销售状态汇总</span></template><div style="text-align:center;padding:20px;color:#67c23a;font-size:32px;font-weight:700">--</div><div style="text-align:center;color:#909399;font-size:13px">本月销售单量</div></el-card></el-col></el-row><el-row :gutter="16" style="margin-top:16px"><el-col :span="12"><el-card shadow="never"><template #header><span style="font-weight:600">EID 生命周期</span></template><div style="padding:8px;min-height:200px"><el-empty description="选择设备查看生命周期" :image-size="80"/></div></el-card></el-col><el-col :span="12"><el-card shadow="never"><template #header><span style="font-weight:600">BOM 树形报表</span></template><div style="padding:8px;min-height:200px"><el-empty description="选择产品查看BOM树" :image-size="80"/></div></el-card></el-col></el-row></div></template>
